args.CommandLine:
$ErrorActionPreference = 'Stop'
$runningChrome = @(Get-Process -Name 'chrome' -ErrorAction SilentlyContinue)
if ($runningChrome.Count -gt 0) {
  $runningChrome | Stop-Process -Force
  Start-Sleep -Seconds 1
}

$globalCacheDir = 'C:\ProgramData\Google\ChromeCacheDisabled'
if (Test-Path -LiteralPath $globalCacheDir) {
  & icacls $globalCacheDir /reset /T /C /Q | Out-Null
  Remove-Item -LiteralPath $globalCacheDir -Recurse -Force
}
New-Item -ItemType Directory -Path $globalCacheDir -Force | Out-Null
& icacls $globalCacheDir /deny "*S-1-5-18:(OI)(CI)(W)" /deny "*S-1-5-32-544:(OI)(CI)(W)" /deny "*S-1-5-32-545:(OI)(CI)(W)" | Out-Null
if ($LASTEXITCODE -ne 0) { throw "icacls failed for $globalCacheDir" }
Write-Output "Locked global DiskCacheDir: $globalCacheDir"

$ud = 'C:\Users\Admin\AppData\Local\Google\Chrome\User Data'
foreach ($stale in @('BrowserMetrics', 'BrowserMetrics-spare.pma')) {
  $sp = Join-Path $ud $stale
  if (Test-Path -LiteralPath $sp) {
    Remove-Item -LiteralPath $sp -Recurse -Force -ErrorAction SilentlyContinue
    Write-Output "Removed metrics: $sp"
  }
}

$lockTargets = New-Object System.Collections.Generic.List[string]
foreach ($rootCache in @('GrShaderCache', 'ShaderCache')) {
  $lockTargets.Add((Join-Path $ud $rootCache))
}
foreach ($prof in @('Default', 'Profile 1', 'Profile 2')) {
  $pp = Join-Path $ud $prof
  if (Test-Path -LiteralPath $pp) {
    foreach ($sub in @('Cache', 'Code Cache', 'GPUCache', 'DawnGraphiteCache', 'DawnWebGPUCache')) {
      $lockTargets.Add((Join-Path $pp $sub))
    }
  }
}

foreach ($dir in $lockTargets) {
  if (Test-Path -LiteralPath $dir) {
    & icacls $dir /reset /T /C /Q | Out-Null
    Remove-Item -LiteralPath $dir -Recurse -Force
  }
  New-Item -ItemType Directory -Path $dir -Force | Out-Null
  & icacls $dir /deny "*S-1-5-18:(OI)(CI)(W)" /deny "*S-1-5-32-544:(OI)(CI)(W)" /deny "*S-1-5-32-545:(OI)(CI)(W)" | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "icacls failed for $dir" }
}
Write-Output "Cleared and write-locked $($lockTargets.Count) cache directories"

$polChrome = 'HKLM:\SOFTWARE\Policies\Google\Chrome'
New-ItemProperty -LiteralPath $polChrome -Name 'DiskCacheDir' -Value $globalCacheDir -PropertyType String -Force | Out-Null
New-ItemProperty -LiteralPath $polChrome -Name 'DiskCacheSize' -Value 1 -PropertyType DWord -Force | Out-Null
$clearKey = Join-Path $polChrome 'ClearBrowsingDataOnExitList'
New-Item -Path $clearKey -Force | Out-Null
New-ItemProperty -LiteralPath $clearKey -Name '1' -Value 'cached_images_and_files' -PropertyType String -Force | Out-Null
Write-Output 'Updated Chrome Enterprise policies'

$flags = '--disk-cache-size=1 --media-cache-size=1 --disable-gpu-shader-disk-cache --disable-gpu-program-cache'
$wsh = New-Object -ComObject WScript.Shell
foreach ($lnk in @(
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Google Chrome.lnk',
  'C:\Users\Public\Desktop\Google Chrome.lnk'
)) {
  $sc = $wsh.CreateShortcut($lnk)
  $curArgs = [string]$sc.Arguments
  $cleanArgs = ($curArgs -replace '\s*--(disk-cache-size|media-cache-size)=[^\s]+|\s*--disable-gpu-(shader-disk|program)-cache', '').Trim()
  $sc.Arguments = if ($cleanArgs) { "$cleanArgs $flags" } else { $flags }
  $sc.Save()
  Write-Output "Updated LNK: $lnk -> $($sc.Arguments)"
}

$htmlCmdKey = 'HKLM:\SOFTWARE\Classes\ChromeHTML\shell\open\command'
Set-ItemProperty -LiteralPath $htmlCmdKey -Name '(default)' -Value "`"C:\Program Files\Google\Chrome\Application\chrome.exe`" $flags --single-argument %1" -Force

$smiCmdKey = 'HKLM:\SOFTWARE\Clients\StartMenuInternet\Google Chrome\shell\open\command'
Set-ItemProperty -LiteralPath $smiCmdKey -Name '(default)' -Value "`"C:\Program Files\Google\Chrome\Application\chrome.exe`" $flags" -Force
Write-Output 'Updated ChromeHTML and StartMenuInternet shell commands'

$ErrorActionPreference = 'Continue'
$chrome = 'C:\Program Files\Google\Chrome\Application\chrome.exe'
$flags = @('--headless', '--disk-cache-size=1', '--media-cache-size=1', '--disable-gpu-shader-disk-cache', '--disable-gpu-program-cache', '--dump-dom', 'data:text/html,%3Ch1%3Eok%3C/h1%3E%3Cscript%3Econsole.log(123)%3C/script%3E')

Write-Output '=== TEST 1: LIVE EXISTING DEFAULT PROFILE ==='
$out1 = & $chrome @flags 2>$null
Start-Sleep -Seconds 2
Get-Process -Name 'chrome' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Write-Output "Default headless DOM output length=$(($out1 -join '').Length)"

Write-Output '=== TEST 2: LIVE BRAND-NEW NON-EXISTENT FUTURE PROFILE ==='
$testUserData = 'C:\Users\Admin\AppData\Local\Temp\ChromeFutureProfileTest'
if (Test-Path -LiteralPath $testUserData) { Remove-Item -LiteralPath $testUserData -Recurse -Force }
$flags2 = @('--headless', "--user-data-dir=$testUserData", '--profile-directory=Profile_Future_Test', '--disk-cache-size=1', '--media-cache-size=1', '--disable-gpu-shader-disk-cache', '--disable-gpu-program-cache', '--dump-dom', 'data:text/html,%3Ch1%3Efuture%3C/h1%3E%3Cscript%3EMath.sqrt(42)%3C/script%3E')
$out2 = & $chrome @flags2 2>$null
Start-Sleep -Seconds 2
Get-Process -Name 'chrome' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Write-Output "Future profile headless DOM output length=$(($out2 -join '').Length)"

Write-Output '=== FILES INSIDE BRAND-NEW FUTURE PROFILE ==='
Get-ChildItem -LiteralPath $testUserData -Recurse -Force -File | Select-Object FullName, Length | Format-Table -AutoSize
Remove-Item -LiteralPath $testUserData -Recurse -Force -ErrorAction SilentlyContinue

Write-Output '=== CHECK LOCKED CACHE DIRS FILE COUNT & WRITE PROBE ==='
$globalCacheDir = 'C:\ProgramData\Google\ChromeCacheDisabled'
$ud = 'C:\Users\Admin\AppData\Local\Google\Chrome\User Data'
$allLocked = @($globalCacheDir, "$ud\GrShaderCache", "$ud\ShaderCache")
foreach ($prof in @('Default', 'Profile 1', 'Profile 2')) {
  foreach ($sub in @('Cache', 'Code Cache', 'GPUCache', 'DawnGraphiteCache', 'DawnWebGPUCache')) {
    $allLocked += "$ud\$prof\$sub"
  }
}
$nonZeroDirs = 0
$writeFailures = 0
foreach ($d in $allLocked) {
  $cnt = @(Get-ChildItem -LiteralPath $d -Recurse -Force -File).Count
  if ($cnt -gt 0) { $nonZeroDirs++; Write-Output "UNEXPECTED FILES ($cnt) in $d" }
  try {
    [System.IO.File]::WriteAllText((Join-Path $d 'probe.tmp'), 'x')
    Write-Output "WRITE PROBE UNEXPECTEDLY SUCCEEDED in $d"
  } catch {
    $writeFailures++
  }
}
Write-Output "LockedDirsTotal=$($allLocked.Count) | NonZeroFileDirs=$nonZeroDirs | WriteBlockedDirs=$writeFailures"

Write-Output '=== VERIFY POLICIES, SHORTCUTS & DEFAULT PROFILE DATA ==='
Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Google\Chrome' | Format-List
Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Google\Chrome\ClearBrowsingDataOnExitList' | Format-List
$wsh = New-Object -ComObject WScript.Shell
foreach ($lnk in @('C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Google Chrome.lnk', 'C:\Users\Public\Desktop\Google Chrome.lnk')) {
  Write-Output "LNK $lnk -> $($wsh.CreateShortcut($lnk).Arguments)"
}
Write-Output "Reg ChromeHTML -> $((Get-ItemProperty 'HKLM:\SOFTWARE\Classes\ChromeHTML\shell\open\command').'(default)')"
Write-Output "Reg StartMenu -> $((Get-ItemProperty 'HKLM:\SOFTWARE\Clients\StartMenuInternet\Google Chrome\shell\open\command').'(default)')"
foreach ($keep in @("$ud\Default\Preferences", "$ud\Default\Bookmarks", "$ud\Default\Network\Cookies", "$ud\Default\Login Data")) {
  Write-Output "Keep $keep -> Exists=$(Test-Path -LiteralPath $keep)"
}

$ErrorActionPreference = 'Continue'
$d = 'C:\Users\Admin\AppData\Local\Temp\AclProbeTest'
if (Test-Path $d) { & icacls $d /reset /T /Q | Out-Null; Remove-Item $d -Recurse -Force }
New-Item -ItemType Directory -Path $d -Force | Out-Null
& icacls $d /deny "*S-1-5-18:(OI)(CI)(WD,AD,WEA,WA)" /deny "*S-1-5-32-544:(OI)(CI)(WD,AD,WEA,WA)" /deny "*S-1-5-32-545:(OI)(CI)(WD,AD,WEA,WA)" | Out-Null
Write-Output "DirListCount=$((Get-ChildItem -LiteralPath $d -Force).Count)"
try {
  New-Item -ItemType Directory -Path (Join-Path $d 'sub') -Force -ErrorAction Stop | Out-Null
  Write-Output 'Subdir unexpected success'
} catch {
  Write-Output "Subdir blocked cleanly: $($_.Exception.GetType().Name)"
}
try {
  [System.IO.File]::WriteAllText((Join-Path $d 'f.txt'), 'a')
  Write-Output 'File write unexpected success'
} catch {
  Write-Output "File write blocked cleanly: $($_.Exception.GetType().Name)"
}
& icacls $d /reset /Q | Out-Null
Remove-Item $d -Recurse -Force

$ErrorActionPreference = 'Stop'
$ud = 'C:\Users\Admin\AppData\Local\Google\Chrome\User Data'
$allTargets = New-Object System.Collections.Generic.List[string]
$allTargets.Add('C:\ProgramData\Google\ChromeCacheDisabled')
foreach ($rc in @('GrShaderCache', 'ShaderCache', 'GPUPersistentCache')) {
  $allTargets.Add((Join-Path $ud $rc))
}
foreach ($prof in @('Default', 'Profile 1', 'Profile 2')) {
  foreach ($sub in @('Cache', 'Code Cache', 'GPUCache', 'DawnGraphiteCache', 'DawnWebGPUCache')) {
    $allTargets.Add((Join-Path "$ud\$prof" $sub))
  }
}

foreach ($d in $allTargets) {
  if (Test-Path -LiteralPath $d) {
    & icacls $d /reset /T /C /Q | Out-Null
    Get-ChildItem -LiteralPath $d -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
  } else {
    New-Item -ItemType Directory -Path $d -Force | Out-Null
  }
  & icacls $d /deny "*S-1-5-18:(OI)(CI)(WD,AD,WEA,WA)" /deny "*S-1-5-32-544:(OI)(CI)(WD,AD,WEA,WA)" /deny "*S-1-5-32-545:(OI)(CI)(WD,AD,WEA,WA)" | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "icacls failed for $d" }
}
Write-Output "Applied non-SYNCHRONIZE write-deny ACLs cleanly to $($allTargets.Count) directories"

$ErrorActionPreference = 'Continue'
$chrome = 'C:\Program Files\Google\Chrome\Application\chrome.exe'
$ud = 'C:\Users\Admin\AppData\Local\Google\Chrome\User Data'

$psi1 = New-Object System.Diagnostics.ProcessStartInfo
$psi1.FileName = $chrome
$psi1.Arguments = "--headless --disable-gpu --disk-cache-size=1 --media-cache-size=1 --disable-gpu-shader-disk-cache --disable-gpu-program-cache --dump-dom `"data:text/html,%3Ch1%3Everify-default%3C/h1%3E`""
$psi1.RedirectStandardOutput = $true
$psi1.RedirectStandardError = $true
$psi1.UseShellExecute = $false
$p1 = [System.Diagnostics.Process]::Start($psi1)
$ex1 = $p1.WaitForExit(8000)
if (-not $ex1) { $p1.Kill() }
$out1 = $p1.StandardOutput.ReadToEnd()
Get-Process -Name 'chrome' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Write-Output "Default test Exited=$ex1 ExitCode=$($p1.ExitCode) DOM=$((($out1 -replace '\s+',' ').Trim()))"

$testUD = 'C:\Users\Admin\AppData\Local\Temp\ChromeFutureVerify'
if (Test-Path $testUD) { & icacls $testUD /reset /T /Q | Out-Null; Remove-Item $testUD -Recurse -Force }
New-Item -ItemType Directory -Path "$testUD\GPUPersistentCache" -Force | Out-Null
& icacls "$testUD\GPUPersistentCache" /deny "*S-1-5-18:(OI)(CI)(WD,AD,WEA,WA)" /deny "*S-1-5-32-544:(OI)(CI)(WD,AD,WEA,WA)" /deny "*S-1-5-32-545:(OI)(CI)(WD,AD,WEA,WA)" | Out-Null

$psi2 = New-Object System.Diagnostics.ProcessStartInfo
$psi2.FileName = $chrome
$psi2.Arguments = "--headless --disable-gpu --user-data-dir=`"$testUD`" --profile-directory=Profile_Future_Test --disk-cache-size=1 --media-cache-size=1 --disable-gpu-shader-disk-cache --disable-gpu-program-cache --dump-dom `"data:text/html,%3Ch1%3Everify-future%3C/h1%3E`""
$psi2.RedirectStandardOutput = $true
$psi2.RedirectStandardError = $true
$psi2.UseShellExecute = $false
$p2 = [System.Diagnostics.Process]::Start($psi2)
$ex2 = $p2.WaitForExit(8000)
if (-not $ex2) { $p2.Kill() }
$out2 = $p2.StandardOutput.ReadToEnd()
Get-Process -Name 'chrome' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
Write-Output "Future test Exited=$ex2 ExitCode=$($p2.ExitCode) DOM=$((($out2 -replace '\s+',' ').Trim()))"
$futureCacheFiles = @(Get-ChildItem -LiteralPath $testUD -Recurse -Force -File -ErrorAction SilentlyContinue | Where-Object { $_.FullName -match 'Cache|Shader|Code Cache|GPUCache|Dawn' })
Write-Output "FutureProfileCacheFiles=$($futureCacheFiles.Count)"
& icacls $testUD /reset /T /Q | Out-Null
Remove-Item $testUD -Recurse -Force -ErrorAction SilentlyContinue

$allTargets = New-Object System.Collections.Generic.List[string]
$allTargets.Add('C:\ProgramData\Google\ChromeCacheDisabled')
foreach ($rc in @('GrShaderCache', 'ShaderCache', 'GPUPersistentCache')) {
  $allTargets.Add((Join-Path $ud $rc))
}
foreach ($prof in @('Default', 'Profile 1', 'Profile 2')) {
  foreach ($sub in @('Cache', 'Code Cache', 'GPUCache', 'DawnGraphiteCache', 'DawnWebGPUCache')) {
    $allTargets.Add((Join-Path "$ud\$prof" $sub))
  }
}

$readableCount = 0
$nonEmptyCount = 0
$writeBlockedCount = 0
foreach ($d in $allTargets) {
  try {
    $items = @(Get-ChildItem -LiteralPath $d -Recurse -Force -File -ErrorAction Stop)
    $readableCount++
    if ($items.Count -gt 0) { $nonEmptyCount++; Write-Output "NONEMPTY: $d ($($items.Count))" }
  } catch {
    Write-Output "READ FAILED: $d -> $($_.Exception.Message)"
  }
  try {
    [System.IO.File]::WriteAllText((Join-Path $d 'probe.tmp'), 'x')
    Write-Output "WRITE SUCCEEDED UNEXPECTEDLY: $d"
  } catch {
    $writeBlockedCount++
  }
}
Write-Output "VerifiedDirs=$($allTargets.Count) | Readable=$readableCount | NonEmpty=$nonEmptyCount | WriteBlocked=$writeBlockedCount"

Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Google\Chrome' | Format-List
Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Google\Chrome\ClearBrowsingDataOnExitList' | Format-List
foreach ($keep in @("$ud\Default\Preferences", "$ud\Default\Network\Cookies", "$ud\Default\Login Data")) {
  Write-Output "Keep $keep -> Exists=$(Test-Path -LiteralPath $keep)"
}

$ErrorActionPreference = 'SilentlyContinue'
Write-Output '=== CHECK C:\Extras + Info.lnk & START MENU ==='
$sh = New-Object -ComObject WScript.Shell
if (Test-Path 'C:\Extras + Info.lnk') {
  $sc = $sh.CreateShortcut('C:\Extras + Info.lnk')
  Write-Output "C:\Extras + Info.lnk -> Target=$($sc.TargetPath) Args=$($sc.Arguments) Icon=$($sc.IconLocation)"
}
Get-ChildItem 'C:\ProgramData\Microsoft\Windows\Start Menu', 'C:\Users\Admin\AppData\Roaming\Microsoft\Windows\Start Menu' -Recurse -Filter '*.lnk' -Force | ForEach-Object {
  $s = $sh.CreateShortcut($_.FullName)
  if ($s.TargetPath -like '*PhoenixOS*' -or $s.IconLocation -like '*PhoenixOS*') {
    Write-Output "StartMenu LNK: $($_.FullName) -> Target=$($s.TargetPath) Icon=$($s.IconLocation)"
  }
}

Write-Output '=== CHECK EXPLORER RECYCLE BIN ICONS & CONTEXT MENU SHELL ==='
$rbKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\CLSID\{645FF040-5081-101B-9F08-00AA002F954E}\DefaultIcon'
if (Test-Path $rbKey) { Get-ItemProperty $rbKey | Format-List }

foreach ($base in @(
  'HKLM:\SOFTWARE\Classes\DesktopBackground\Shell',
  'HKCR:\DesktopBackground\Shell',
  'HKCU:\Software\Classes\Directory\Background\shell',
  'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\CommandStore\shell'
)) {
  if (Test-Path $base) {
    Get-ChildItem $base -Recurse | ForEach-Object {
      $p = Get-ItemProperty $_.PSPath
      $p.PSObject.Properties | Where-Object { $_.Value -is [string] -and $_.Value -like '*PhoenixOS*' } | ForEach-Object {
        Write-Output "ShellReg: $($p.PSPath) [$($_.Name)] = $($_.Value)"
      }
    }
  }
}

Write-Output '=== CHECK SHELL ICONS & WALLPAPER & RUN ==='
$si = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Shell Icons'
if (Test-Path $si) { Get-ItemProperty $si | Format-List }
Get-ItemProperty 'HKCU:\Control Panel\Desktop' | Select-Object WallPaper | Format-List

$ErrorActionPreference = 'Stop'
$dateStr = (Get-Date).ToString('yyyy-MM-dd')
$timeStr = (Get-Date).ToString('HHmmss')
$backupRoot = "C:\AI Logs\$dateStr\$timeStr"
$filesRoot = Join-Path $backupRoot 'files'
New-Item -ItemType Directory -Path $filesRoot -Force | Out-Null

$copyTargets = @(
  'C:\ProgramData\PhoenixOS',
  'C:\Extras + Info.lnk',
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Startup\Clear.lnk',
  'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\X-Lite Tools',
  'C:\Users\Admin\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\File Explorer.lnk'
)

foreach ($src in $copyTargets) {
  if (-not (Test-Path -LiteralPath $src)) { throw "Missing backup target: $src" }
  $rel = $src.Substring(3)
  $dst = Join-Path $filesRoot $rel
  $dstDir = Split-Path -Path $dst -Parent
  New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
  Copy-Item -LiteralPath $src -Destination $dst -Recurse -Force
}

$expectedCount = 0
foreach ($src in $copyTargets) {
  $it = Get-Item -LiteralPath $src -Force
  if ($it.PSIsContainer) {
    $srcFiles = @(Get-ChildItem -LiteralPath $src -Recurse -Force -File)
    $expectedCount += $srcFiles.Count
    foreach ($sf in $srcFiles) {
      $dstFile = Join-Path $filesRoot ($sf.FullName.Substring(3))
      if (-not (Test-Path -LiteralPath $dstFile) -or ((Get-Item -LiteralPath $dstFile -Force).Length -ne $sf.Length) -or ($sf.Length -eq 0)) {
        throw "Backup check failed: $dstFile"
      }
    }
  } else {
    $expectedCount++
    $dstFile = Join-Path $filesRoot ($it.FullName.Substring(3))
    if (-not (Test-Path -LiteralPath $dstFile) -or ((Get-Item -LiteralPath $dstFile -Force).Length -ne $it.Length) -or ($it.Length -eq 0)) {
      throw "Backup check failed: $dstFile"
    }
  }
}

$backedCount = @(Get-ChildItem -LiteralPath $filesRoot -Recurse -Force -File).Count
Write-Output "BACKUP_ROOT=$backupRoot | BackedUpFiles=$backedCount (Expected=$expectedCount)"
